window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9d45a12dff2b743a"]={"versions": [{"id": "FIG-9d45a12dff2b743a", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Daten- und Mapping-Diagramm im Kontext der Signal-Service-Translation (Signal-to-Service-Mapping) nach AUTOSAR Adaptive Platform / TPS Manifest Specification. Das Diagramm illustriert das Zusammenspiel von signalbasierten Kommunikationsstrukturen (Classic Platform bzw. CAN/LIN/FlexRay-Frames) mit serviceorientierten Ereignissen (<code>event xyz</code>) unter Verwendung von Update-Bits (<code>updateBit</code>) und optionalen Event-Feldern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm unterteilt sich in zwei logische Bereiche (Spezifikation/Mapping links und Laufzeitbeispiel/Wertebelegung rechts):</p>\n<ul class=\"fig-list\"><li><strong>Signal-Seite (grün hinterlegt):</strong>\n<ul class=\"fig-list\"><li>Signalgruppe <code>x1</code> mit vier Elementen/Signalen: <code>a : uint8</code>, <code>b : uint16</code>, <code>c : boolean</code>, <code>d : sint8</code>.\n</li><li>Einzelsignale: <code>signal y : uint8</code>, <code>signal z : sint16</code>.\n</li><li>Zugeordnete Update-Bits: <code>updateBit_x1</code>, <code>updateBit_y</code>, <code>updateBit_z</code>.\n</li></ul>\n</li><li><strong>Service-/Event-Seite (grau-blau hinterlegt):</strong>\n<ul class=\"fig-list\"><li>Service-Ereignis <code>event xyz</code>.\n</li><li>Feld bzw. Elementstruktur <code>x1 [optional]</code> mit identischen Sub-Elementen (<code>a : uint8</code>, <code>b : uint16</code>, <code>c : boolean</code>, <code>d : sint8</code>).\n</li><li>Optionale Felder: <code>y [optional] : uint8</code>, <code>z [optional] : sint16</code>.\n</li></ul>\n</li><li><strong>Mapping-Beziehungen (gerichtete Pfeile):</strong>\n<ul class=\"fig-list\"><li>Direkte Zuordnung der Signale aus Signalgruppe <code>x1</code> auf die Sub-Elemente von <code>x1 [optional]</code>.\n</li><li>Abbildung von <code>signal y</code> auf <code>y [optional]</code>.\n</li><li>Abbildung von <code>signal z</code> auf <code>z [optional]</code>.\n</li></ul>\n</li><li><strong>Laufzeit-Instanz:</strong>\n<ul class=\"fig-list\"><li>Belegte Signalgruppe <code>x1</code> (<code>a: 3</code>, <code>b: 45</code>, <code>c: true</code>, <code>d: -23</code>) mit <code>updateBit_x1 = 0</code>.\n</li><li>Belegtes Signal <code>signal y: 12</code> mit <code>updateBit_y = 1</code>.\n</li><li>Belegtes Signal <code>signal z: 65</code> mit <code>updateBit_z = 0</code>.\n</li><li>Resultierendes serialisiertes Event <code>event xyz { y : 12 }</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Zustandsauswertung der Update-Bits:</strong> Bei der Konvertierung von eingehenden Signalen in ein Service-Event prüft der Übersetzungsmechanismus (Signal-to-Service-Gateway/Translator) den Status der Update-Bits.\n</li><li><strong>Filterung / Relevanzprüfung:</strong> Ein Signal bzw. eine Signalgruppe gilt nur dann als aktualisiert und serialisierungsrelevant, wenn das zugehörige Update-Bit gesetzt ist (<code>1</code>). Im dargestellten Beispielfall ist <code>updateBit_y = 1</code>, während <code>updateBit_x1 = 0</code> und <code>updateBit_z = 0</code> sind.\n</li><li><strong>Serialisierung des Events:</strong> Da nur <code>y</code> aktualisiert wurde, werden die optionalen Felder <code>x1</code> und <code>z</code> für die Übertragung im Event verworfen bzw. nicht serialisiert. Das Event <code>event xyz</code> enthält zur Laufzeit ausschließlich das aktualisierte Feld <code>{ y : 12 }</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Modellierungsanforderung:</strong> Die Abbildung von Signalen/Signalgruppen auf optionale Event-Felder (<code>[optional]</code>) ermöglicht eine bandbreitenschonende Serialisierung (z. B. SOME/IP mit TLV-Codierung für optionale Member).\n</li><li><strong>Update-Bit-Semantik:</strong> Update-Bits steuern direkt die Präsenz (<code>presence</code>) optionaler Datenfelder im SOME/IP- bzw. Service-Payload.\n</li><li><strong>Konsistenz:</strong> Für aggregierte Datentypen (Signalgruppen) existiert ein gemeinsames Update-Bit (<code>updateBit_x1</code>), welches die Konsistenz und gleichzeitige Übernahme aller Gruppen-Member steuert.\n</li><li><strong>Implementierungshinweis:</strong> Bei Empfang einer signalbasierten PDU ohne gesetztes Update-Bit darf der Serializer das entsprechende optionale Element im Ziel-Event nicht übertragen, selbst wenn gültige Nutzdaten im Signalpuffer anliegen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1013712ac6e6f277", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Daten- und Mapping-Diagramm im Kontext der Signal-Service-Translation (Signal-to-Service-Mapping) nach AUTOSAR Adaptive Platform / TPS Manifest Specification. Das Diagramm illustriert das Zusammenspiel von signalbasierten Kommunikationsstrukturen (Classic Platform bzw. CAN/LIN/FlexRay-Frames) mit serviceorientierten Ereignissen (<code>event xyz</code>) unter Verwendung von Update-Bits (<code>updateBit</code>) und optionalen Event-Feldern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm unterteilt sich in zwei logische Bereiche (Spezifikation/Mapping links und Laufzeitbeispiel/Wertebelegung rechts):</p>\n<ul class=\"fig-list\"><li><strong>Signal-Seite (grün hinterlegt):</strong>\n<ul class=\"fig-list\"><li>Signalgruppe <code>x1</code> mit vier Elementen/Signalen: <code>a : uint8</code>, <code>b : uint16</code>, <code>c : boolean</code>, <code>d : sint8</code>.\n</li><li>Einzelsignale: <code>signal y : uint8</code>, <code>signal z : sint16</code>.\n</li><li>Zugeordnete Update-Bits: <code>updateBit_x1</code>, <code>updateBit_y</code>, <code>updateBit_z</code>.\n</li></ul>\n</li><li><strong>Service-/Event-Seite (grau-blau hinterlegt):</strong>\n<ul class=\"fig-list\"><li>Service-Ereignis <code>event xyz</code>.\n</li><li>Feld bzw. Elementstruktur <code>x1 [optional]</code> mit identischen Sub-Elementen (<code>a : uint8</code>, <code>b : uint16</code>, <code>c : boolean</code>, <code>d : sint8</code>).\n</li><li>Optionale Felder: <code>y [optional] : uint8</code>, <code>z [optional] : sint16</code>.\n</li></ul>\n</li><li><strong>Mapping-Beziehungen (gerichtete Pfeile):</strong>\n<ul class=\"fig-list\"><li>Direkte Zuordnung der Signale aus Signalgruppe <code>x1</code> auf die Sub-Elemente von <code>x1 [optional]</code>.\n</li><li>Abbildung von <code>signal y</code> auf <code>y [optional]</code>.\n</li><li>Abbildung von <code>signal z</code> auf <code>z [optional]</code>.\n</li></ul>\n</li><li><strong>Laufzeit-Instanz:</strong>\n<ul class=\"fig-list\"><li>Belegte Signalgruppe <code>x1</code> (<code>a: 3</code>, <code>b: 45</code>, <code>c: true</code>, <code>d: -23</code>) mit <code>updateBit_x1 = 0</code>.\n</li><li>Belegtes Signal <code>signal y: 12</code> mit <code>updateBit_y = 1</code>.\n</li><li>Belegtes Signal <code>signal z: 65</code> mit <code>updateBit_z = 0</code>.\n</li><li>Resultierendes serialisiertes Event <code>event xyz { y : 12 }</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Zustandsauswertung der Update-Bits:</strong> Bei der Konvertierung von eingehenden Signalen in ein Service-Event prüft der Übersetzungsmechanismus (Signal-to-Service-Gateway/Translator) den Status der Update-Bits.\n</li><li><strong>Filterung / Relevanzprüfung:</strong> Ein Signal bzw. eine Signalgruppe gilt nur dann als aktualisiert und serialisierungsrelevant, wenn das zugehörige Update-Bit gesetzt ist (<code>1</code>). Im dargestellten Beispielfall ist <code>updateBit_y = 1</code>, während <code>updateBit_x1 = 0</code> und <code>updateBit_z = 0</code> sind.\n</li><li><strong>Serialisierung des Events:</strong> Da nur <code>y</code> aktualisiert wurde, werden die optionalen Felder <code>x1</code> und <code>z</code> für die Übertragung im Event verworfen bzw. nicht serialisiert. Das Event <code>event xyz</code> enthält zur Laufzeit ausschließlich das aktualisierte Feld <code>{ y : 12 }</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Modellierungsanforderung:</strong> Die Abbildung von Signalen/Signalgruppen auf optionale Event-Felder (<code>[optional]</code>) ermöglicht eine bandbreitenschonende Serialisierung (z. B. SOME/IP mit TLV-Codierung für optionale Member).\n</li><li><strong>Update-Bit-Semantik:</strong> Update-Bits steuern direkt die Präsenz (<code>presence</code>) optionaler Datenfelder im SOME/IP- bzw. Service-Payload.\n</li><li><strong>Konsistenz:</strong> Für aggregierte Datentypen (Signalgruppen) existiert ein gemeinsames Update-Bit (<code>updateBit_x1</code>), welches die Konsistenz und gleichzeitige Übernahme aller Gruppen-Member steuert.\n</li><li><strong>Implementierungshinweis:</strong> Bei Empfang einer signalbasierten PDU ohne gesetztes Update-Bit darf der Serializer das entsprechende optionale Element im Ziel-Event nicht übertragen, selbst wenn gültige Nutzdaten im Signalpuffer anliegen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9d45a12dff2b743a", "to": "FIG-1013712ac6e6f277", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
